import React from 'react';
import { Link } from 'react-router-dom';
import { postsData } from '../pages/posts'; 
import '../styles/UltimasPublicaciones.css';

// Tomamos las 3 publicaciones más recientes (ya están ordenadas en posts.js)
const publicacionesRecientes = postsData.slice(0, 3);

const UltimasPublicaciones = () => {
  return (
    <section className="ultimas-publicaciones-section">
      <div className="container">
        <h2 className="ultimas-publicaciones-titulo">Mantente Informado</h2>
        <p className="ultimas-publicaciones-subtitulo">Lee nuestros últimos artículos y consejos de expertos.</p>
        <div className="publicaciones-grid">
          {publicacionesRecientes.map(post => (
            <Link to={`/blog/${post.slug}`} key={post.id} className="publicacion-card">
              <img src={post.imageUrl} alt={post.title} className="publicacion-card-image" loading="lazy" />
              <div className="publicacion-card-content">
                <span className="publicacion-card-date">{post.displayDate}</span>
                <h3 className="publicacion-card-title">{post.title}</h3>
                <p className="publicacion-card-summary">{post.summary}</p>
              </div>
            </Link>
          ))}
        </div>
        <Link to="/blog" className="btn-ver-todos">Ver todas las publicaciones</Link>
      </div>
    </section>
  );
};

export default UltimasPublicaciones;
